sys_script_include.script:
var CiscoSecureAccessCredentials = Class.create();
CiscoSecureAccessCredentials.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    createProfileAndFetchToken: function() {
        var clientKey = this.getParameter("client_key");  
        var clientSecret = this.getParameter("client_secret");
        if (!clientKey || !clientSecret) {
            return "❌ Client Key and Secret are required!";
        }

        try {
            var profileName = "Cisco Secure Access Auth Profile";
            var newProfileId = "";

            // 🔎 Check if Basic Auth Profile exists
            var existing = new GlideRecord("sys_auth_profile_basic");
            existing.addQuery("name", profileName);
            existing.query();
            if (existing.next()) {
                gs.info("ℹ️ Found existing Basic Auth Profile: " + existing.sys_id);
                newProfileId = existing.sys_id.toString();

                // optionally update username/password if you want to refresh credentials
                existing.username = clientKey;
                existing.password = clientSecret;
                existing.update();
            } else {
                // 🚀 Create only if not found
                var bap = new GlideRecord("sys_auth_profile_basic");
                bap.initialize();
                bap.name = profileName;
                bap.username = clientKey;  
                bap.password = clientSecret;
                newProfileId = bap.insert();

                if (newProfileId) {
                    gs.info("✅ Created new Basic Auth Profile with sys_id: " + newProfileId);
                } else {
                    gs.error("❌ Failed to create Basic Auth Profile");
                    return "❌ Failed to create Basic Auth Profile";
                }
            }

            // 🔐 Build Authorization header manually
            var authString = clientKey + ":" + clientSecret;
            var encodedAuth = GlideStringUtil.base64Encode(authString);

            // 🌐 Call Cisco API
            var r = new sn_ws.RESTMessageV2();
            r.setEndpoint("https://api.sse.cisco.com/auth/v2/token");
            r.setHttpMethod("GET");
            r.setRequestHeader("Authorization", "Basic " + encodedAuth);

            var resp = r.execute();
            var status = resp.getStatusCode();
            var body = resp.getBody();

            gs.info(" Cisco Secure Access API Call Status: " + status);
            gs.info(" Cisco Secure Access API Response: " + body);

            if (status != 200) {
                return "❌ Failed to fetch token. HTTP Status: " + status + " Body: " + body;
            }

            // Parse response
            var parsed;
            try {
                parsed = JSON.parse(body);
            } catch (e) {
                gs.error("❌ Failed to parse token response: " + e.message);
                return "❌ Failed to parse response";
            }

            if (!parsed.access_token) {
                return "❌ No access_token found in response";
            }

            var expires = parsed.expires_in;
            var expiry = new GlideDateTime();
            expiry.addSeconds(expires);

            // Clean old tokens
            var oldTokens = new GlideRecord("u_cisco_secure_access_token");
            oldTokens.query();
            while (oldTokens.next()) {
                oldTokens.deleteRecord();
            }

            // Store new token
            var gr = new GlideRecord("u_cisco_secure_access_token");
            gr.initialize();
            gr.u_access_token = parsed.access_token;
            gr.u_token_type = parsed.token_type;
            gr.u_expiry_date_time = expiry;
            gr.u_expires_in = expires;
            gr.u_status = "Active";
            gr.u_created_on = new GlideDateTime();
            var tokenId = gr.insert();

            gs.info("✅ Token stored successfully with sys_id: " + tokenId);

            return "✅ Token successfully fetched and stored. Expires in: " + parsed.expires_in + " seconds";

        } catch (ex) {
            gs.error("CiscoSecureAccessCredentials Error: " + ex.message);
            return "❌ Error: " + ex.message;
        }
    },

    type: "CiscoSecureAccessCredentials"
});
